64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
73	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /**
79	     * Common street-type abbreviations expanded during address normalization, keyed by the
80	     * upper-cased abbreviation.
81	     */
82	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
83	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
84	
85	    /**
86	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
87	     * city already holds this many owners.
88	     */
89	    private static final int CITY_CAPACITY = 50;
90	
91	    /**
92	     * Maximum number of owners that may be created on a single day. A create is rejected once this
93	     * many owners already carry the current day as their {@code registrationDate}.
94	     */
95	    private static final int DAILY_OWNER_LIMIT = 100;
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        validateRequiredFields(ownerFieldsDto);
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
147	        LocalDate effectiveDate = owner.getRegistrationDate() == null
148	            ? LocalDate.now()
149	            : owner.getRegistrationDate();
150	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
151	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
152	        rejectWhenCityAtCapacity(owner.getCity());
153	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
154	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
155	        rejectDuplicateTelephone(telephone);
156	        owner.setTelephone(telephone);
157	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
158	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
159	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        this.clinicService.saveOwner(owner);
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    /**
169	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
170	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
171	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
172	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
173	     *
174	     * @param city     the owner's city
175	     * @param lastName the owner's last name
176	     * @return the assigned customer code
177	     */
178	    private String nextCustomerCode(String city, String lastName) {
179	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
180	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
181	        int sequence = (int) this.clinicService.findAllOwners().stream()
182	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
183	            .count() + 1;
184	        return String.format("%s-%s-%04d", city3, last3, sequence);
185	    }
186	
187	    /**
188	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
189	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
190	     *
191	     * @param customerCode     the owner's assigned customer code
192	     * @param registrationDate the owner's registration date
193	     * @return the assigned membership number
194	     */
195	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
196	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
197	    }
198	
199	    /**
200	     * Counts the existing owners that already share the given firstName and lastName, compared
201	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
202	     * the owners that pre-existed this create.
203	     *
204	     * @param firstName the new owner's first name
205	     * @param lastName  the new owner's last name
206	     * @return the number of existing namesakes
207	     */
208	    private int countNamesakes(String firstName, String lastName) {
209	        return (int) this.clinicService.findAllOwners().stream()
210	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
211	                && equalsIgnoreCase(existing.getLastName(), lastName))
212	            .count();
213	    }
214	
215	    /**
216	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
217	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
218	     * customer-code sequence is derived.
219	     *
220	     * @param city the new owner's city
221	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
222	     */
223	    private void rejectWhenCityAtCapacity(String city) {
224	        long count = this.clinicService.findAllOwners().stream()
225	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
226	            .count();
227	        if (count >= CITY_CAPACITY) {
228	            throw new CityAtCapacityException(city);
229	        }
230	    }
231	
232	    /**
233	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
234	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
235	     * business-day registration date, so the limit is enforced per business day and weekend
236	     * requests count against the Monday they roll forward to.
237	     *
238	     * @param registrationDate the owner's adjusted (business-day) registration date
239	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
240	     *                                  registration date
241	     */
242	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
243	        long count = this.clinicService.findAllOwners().stream()
244	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
245	            .count();
246	        if (count >= DAILY_OWNER_LIMIT) {
247	            throw new DailyOwnerLimitException(registrationDate);
248	        }
249	    }
250	
251	    /**
252	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
253	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
254	     * effective registration date (whether supplied in the request or defaulted to the server date)
255	     * so a weekend value never persists as an owner's {@code registrationDate}.
256	     *
257	     * @param date the effective registration date
258	     * @return the same date when it is a weekday, otherwise the next Monday
259	     */
260	    private LocalDate toBusinessDay(LocalDate date) {
261	        return switch (date.getDayOfWeek()) {
262	            case SATURDAY -> date.plusDays(2);
263	            case SUNDAY -> date.plusDays(1);
264	            default -> date;
265	        };
266	    }
267	
268	    private boolean equalsIgnoreCase(String a, String b) {
269	        return a == null ? b == null : a.equalsIgnoreCase(b);
270	    }
271	
272	    /**
273	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
274	     * offending field so the client learns about all of them at once.
275	     *
276	     * @param ownerFieldsDto the submitted owner fields
277	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
278	     *                                     missing or blank
279	     */
280	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
281	        List<String> errors = new ArrayList<>();
282	        if (isBlank(ownerFieldsDto.getFirstName())) {
283	            errors.add("firstName");
284	        }
285	        if (isBlank(ownerFieldsDto.getLastName())) {
286	            errors.add("lastName");
287	        }
288	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
289	            errors.add("address");
290	        }
291	        if (isBlank(ownerFieldsDto.getCity())) {
292	            errors.add("city");
293	        }
294	        if (isBlank(ownerFieldsDto.getTelephone())) {
295	            errors.add("telephone");
296	        }
297	        if (!errors.isEmpty()) {
298	            throw new MissingOwnerFieldsException(errors);
299	        }
300	    }
301	
302	    private boolean isBlank(String value) {
303	        return value == null || value.isBlank();
304	    }
305	
306	    /**
307	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
308	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
309	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
310	     * followed by 8 to 15 digits.
311	     *
312	     * @param telephone the raw telephone value as submitted
313	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
314	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
315	     */
316	    private String normalizeTelephone(String telephone) {
317	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
318	        String nationalSignificantNumber;
319	        if (cleaned.startsWith("+")) {
320	            nationalSignificantNumber = cleaned.substring(1);
321	        } else {
322	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
323	            nationalSignificantNumber = "61" + national;
324	        }
325	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
326	            throw new InvalidTelephoneException(telephone);
327	        }
328	        return "+" + nationalSignificantNumber;
329	    }
330	
331	    /**
332	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
333	     * value is treated as absent and returns {@code null}); when present the value must be a
334	     * syntactically valid address, and is stored and returned lower-cased.
335	     *
336	     * @param email the raw email value as submitted, may be {@code null}
337	     * @return the lower-cased email, or {@code null} when none was supplied
338	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
339	     */
340	    private String normalizeEmail(String email) {
341	        if (email == null || email.isBlank()) {
342	            return null;
343	        }
344	        String normalized = email.trim().toLowerCase();
345	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
346	            throw new InvalidEmailException(email);
347	        }
348	        return normalized;
349	    }
350	
351	    /**
352	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
353	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
354	     * comparison, so numbers that differ only in formatting still count as duplicates.
355	     *
356	     * @param e164Telephone the E.164 telephone of the owner being created
357	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
358	     */
359	    private void rejectDuplicateTelephone(String e164Telephone) {
360	        boolean inUse = this.clinicService.findAllOwners().stream()
361	            .map(Owner::getTelephone)
362	            .filter(existing -> existing != null)
363	            .map(this::toComparableTelephone)
364	            .filter(existing -> existing != null)
365	            .anyMatch(e164Telephone::equals);
366	        if (inUse) {
367	            throw new DuplicateTelephoneException(e164Telephone);
368	        }
369	    }
370	
371	    /**
372	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
373	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
374	     * than aborting the whole create.
375	     */
376	    private String toComparableTelephone(String telephone) {
377	        try {
378	            return normalizeTelephone(telephone);
379	        } catch (InvalidTelephoneException ex) {
380	            return null;
381	        }
382	    }
383	
384	    /**
385	     * Applies the household rule to an owner being created. An owner belongs to the same household
386	     * as an existing owner when their lastName and address both match (compared case-insensitively
387	     * with runs of whitespace collapsed to a single space).
388	     *
389	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
390	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
391	     * does, the new owner and every existing owner in the household are assigned the same stable
392	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
393	     *
394	     * @param owner            the owner being created
395	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
396	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
397	     *                                     the request did not opt in with {@code sharesHousehold=true}
398	     */
399	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
400	        String lastNameKey = toHouseholdKey(owner.getLastName());
401	        String addressKey = toHouseholdKey(owner.getAddress());
402	        List<Owner> household = this.clinicService.findAllOwners().stream()
403	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
404	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
405	            .toList();
406	        if (household.isEmpty()) {
407	            return;
408	        }
409	        if (!Boolean.TRUE.equals(sharesHousehold)) {
410	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
411	        }
412	        String householdId = householdId(lastNameKey, addressKey);
413	        owner.setHouseholdId(householdId);
414	        for (Owner existing : household) {
415	            if (!householdId.equals(existing.getHouseholdId())) {
416	                existing.setHouseholdId(householdId);
417	                this.clinicService.saveOwner(existing);
418	            }
419	        }
420	    }
421	
422	    /**
423	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
424	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
425	     * lastName and address keys. Being a pure function of the household, every owner in it derives
426	     * the same value regardless of creation order.
427	     *
428	     * @param lastNameKey the normalized household lastName key
429	     * @param addressKey  the normalized household address key
430	     * @return the household identifier
431	     */
432	    private String householdId(String lastNameKey, String addressKey) {
433	        try {
434	            byte[] digest = MessageDigest.getInstance("SHA-256")
435	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
436	            StringBuilder hex = new StringBuilder(digest.length * 2);
437	            for (byte b : digest) {
438	                hex.append(String.format("%02x", b));
439	            }
440	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
441	        } catch (NoSuchAlgorithmException ex) {
442	            throw new IllegalStateException("SHA-256 not available", ex);
443	        }
444	    }
445	
446	    /**
447	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
448	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
449	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
450	     * string.
451	     */
452	    private String toHouseholdKey(String value) {
453	        if (value == null) {
454	            return "";
455	        }
456	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
457	    }
458	
459	    /**
460	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
461	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
462	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
463	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
464	     * value, or one that is blank once trimmed, normalizes to an empty string.
465	     *
466	     * @param address the raw address value as submitted, may be {@code null}
467	     * @return the normalized address, or an empty string when none was supplied
468	     */
469	    private String normalizeAddress(String address) {
470	        if (address == null) {
471	            return "";
472	        }
473	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
474	        if (collapsed.isEmpty()) {
475	            return "";
476	        }
477	        String[] tokens = collapsed.split(" ");
478	        StringBuilder normalized = new StringBuilder(collapsed.length());
479	        for (int i = 0; i < tokens.length; i++) {
480	            if (i > 0) {
481	                normalized.append(' ');
482	            }
483	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
484	        }
485	        return normalized.toString();
486	    }
487	
488	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
489	    @Override
490	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
491	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
492	        if (currentOwner == null) {
493	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
494	        }
495	        currentOwner.setAddress(ownerFieldsDto.getAddress());
496	        currentOwner.setCity(ownerFieldsDto.getCity());
497	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
498	        currentOwner.setLastName(ownerFieldsDto.getLastName());
499	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
500	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
501	        this.clinicService.saveOwner(currentOwner);
502	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
503	    }
504	
505	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
506	    @Transactional
507	    @Override
508	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
509	        Owner owner = this.clinicService.findOwnerById(ownerId);
510	        if (owner == null) {
511	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
512	        }
513	        this.clinicService.deleteOwner(owner);
514	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
515	    }
516	
517	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
518	    @Override
519	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
520	        Owner owner = this.clinicService.findOwnerById(ownerId);
521	        if (owner == null) {
522	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
523	        }
524	        HttpHeaders headers = new HttpHeaders();
525	        Pet pet = petMapper.toPet(petFieldsDto);
526	        owner.setId(ownerId);
527	        pet.setOwner(owner);
528	        pet.getType().setName(null);
529	        this.clinicService.savePet(pet);
530	        PetDto petDto = petMapper.toPetDto(pet);
531	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
532	            .buildAndExpand(pet.getId()).toUri());
533	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
534	    }
535	
536	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
537	    @Override
538	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
539	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
540	        if (currentOwner != null) {
541	            Pet currentPet = this.clinicService.findPetById(petId);
542	            if (currentPet != null) {
543	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
544	                currentPet.setName(petFieldsDto.getName());
545	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
546	                this.clinicService.savePet(currentPet);
547	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
548	            }
549	        }
550	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
551	    }
552	
553	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
554	    @Override
555	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
556	        HttpHeaders headers = new HttpHeaders();
557	        Visit visit = visitMapper.toVisit(visitFieldsDto);
558	        Pet pet = new Pet();
559	        pet.setId(petId);
560	        visit.setPet(pet);
561	        this.clinicService.saveVisit(visit);
562	        VisitDto visitDto = visitMapper.toVisitDto(visit);
563	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
564	            .buildAndExpand(visit.getId()).toUri());
565	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
566	    }
567	
568	
569	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
570	    @Override
571	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
572	        Owner owner = this.clinicService.findOwnerById(ownerId);
573	        if (owner != null) {
574	            Pet pet = owner.getPet(petId);
575	            if (pet != null) {
576	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
577	            }
578	        }
579	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
580	    }
581	}
